CREATE TABLE IF NOT EXISTS tenants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_tenant_name(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('superadmin','admin','operator') NOT NULL DEFAULT 'admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sites(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,timezone VARCHAR(64) NOT NULL DEFAULT 'UTC',UNIQUE KEY uq_site(tenant_id,name),FOREIGN KEY(tenant_id) REFERENCES tenants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS playlists(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,orientation ENUM('any','landscape','portrait') NOT NULL DEFAULT 'any',UNIQUE KEY uq_playlist(tenant_id,name),FOREIGN KEY(tenant_id) REFERENCES tenants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS media(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,filename VARCHAR(120) NOT NULL,mime VARCHAR(120) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS playlist_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,playlist_id BIGINT UNSIGNED NOT NULL,kind ENUM('media','playlist') NOT NULL,media_id BIGINT UNSIGNED NULL,child_playlist_id BIGINT UNSIGNED NULL,position INT NOT NULL DEFAULT 0,duration_seconds INT NOT NULL DEFAULT 10,repeat_count INT NOT NULL DEFAULT 1,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(playlist_id) REFERENCES playlists(id) ON DELETE CASCADE,FOREIGN KEY(media_id) REFERENCES media(id) ON DELETE RESTRICT,FOREIGN KEY(child_playlist_id) REFERENCES playlists(id) ON DELETE RESTRICT,INDEX(tenant_id,playlist_id,position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS devices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,site_id BIGINT UNSIGNED NULL,name VARCHAR(160) NOT NULL,orientation ENUM('landscape','portrait') DEFAULT 'landscape',mode TINYINT UNSIGNED NOT NULL DEFAULT 1,width_px INT NULL,height_px INT NULL,last_seen DATETIME NULL,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(site_id) REFERENCES sites(id),UNIQUE KEY uq_device(tenant_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS schedules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,device_id BIGINT UNSIGNED NOT NULL,playlist_id BIGINT UNSIGNED NOT NULL,days_mask TINYINT UNSIGNED NOT NULL DEFAULT 127,start_time TIME NOT NULL,end_time TIME NOT NULL,valid_from DATE NULL,valid_until DATE NULL,priority INT NOT NULL DEFAULT 0,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE,FOREIGN KEY(playlist_id) REFERENCES playlists(id),INDEX(tenant_id,device_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS schema_migrations(id VARCHAR(80) PRIMARY KEY,applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
